// Django already maps WAHA → extract JSON.
// Expect body fields: whatsapp_number, message, message_sid, button_payload, input_channel, media_url…
const item = $input.first().json;
const body = item.body || item;
return [{ json: {
  whatsapp_number: body.whatsapp_number,
  message: body.message,
  message_sid: body.message_sid,
  button_payload: body.button_payload || null,
  button_text: body.button_text || null,
  input_channel: body.input_channel || 'whatsapp_text',
  media_url: body.media_url || null,
  media_content_type: body.media_content_type || null,
} }];
